// Des: Run loop: sitemap seeds, robots, rate, fetch, retry, breaker
// Flo: resume claims > seed from sitemap > pick due URL whose host is ready > robots decision logged > fetch+validate+store > done/fail/DLQ > breaker check > summary
// I/O: seed URLs + Conf + open Db (caller) > Summ counts; rows in fron, page, reco, logz
// ===================================================================
const std = @import("std"); const urln = @import("ut-urlz-norm.zig"); const tmfx = @import("nt-fetc-time.zig"); const robo = @import("pa-robo-txtz.zig"); const smap = @import("pa-site-maps.zig"); const fron = @import("qu-fron-main.zig"); const inde = @import("st-page-inde.zig"); const pipe = @import("ru-page-fetc.zig"); const rate = @import("ru-rate-limi.zig"); const brea = @import("ru-brea-circ.zig"); const sqli = @import("st-stor-sqli.zig"); const cfgz = @import("cf-conf-load.zig"); const ladd = @import("ru-tier-ladd.zig"); const trap = @import("pa-trap-dete.zig"); const site = @import("cf-site-rule.zig"); const file = @import("st-stor-file.zig"); const vbas = @import("nt-vend-base.zig"); const revi = @import("ru-revi-sche.zig");
const CF = .{ .agnt = "scra", .smax = 5000, .subz = 5, .napz = 200, .nmax = 2000, .batz = 16, .perm = @as([]const []const u8, &.{ "NotText", "TooBig", "BadUrl", "BlockedHost", "CharUnsupported", "RedirectLoop", "TooManyRedirects" }) };
pub const Summ = struct { seen: u32 = 0, done: u32 = 0, fail: u32 = 0, skip: u32 = 0, blok: u32 = 0, dead: i64 = 0, uniq: u32 = 0, halt: bool = false, incm: bool = false, trap: u32 = 0 };
pub const Walk = struct { gpaz: std.mem.Allocator, iozz: std.Io, conf: cfgz.Conf, dbzz: *sqli.Dbzz, dirz: []const u8, priv: bool, gapz: i64, base: i64 = 1000, back: ?vbas.Bac2 = null, gozz: bool = false, foll: u32 = 0, geoz: []const u8 = "", rate: rate.Rate, brek: brea.Brea = brea.Brea.init(20, 10, 50), parn: std.heap.ArenaAllocator, robs: std.StringHashMapUnmanaged(robo.Robo) = .empty,
pub fn init(gpaz: std.mem.Allocator, iozz: std.Io, conf: cfgz.Conf, dbzz: *sqli.Dbzz, dirz: []const u8, priv: bool) Walk { return .{ .gpaz = gpaz, .iozz = iozz, .conf = conf, .dbzz = dbzz, .dirz = dirz, .priv = priv, .gapz = @as(i64, conf.rate_host_seco) * 1000, .rate = rate.Rate.init(gpaz, @intCast(@abs(std.Io.Clock.real.now(iozz).toMilliseconds()))), .parn = std.heap.ArenaAllocator.init(gpaz) }; }
pub fn deinit(self: *Walk) void { self.rate.deinit(); self.parn.deinit(); }
fn nowzMill(self: *Walk) i64 { return @intCast(std.Io.Clock.real.now(self.iozz).toMilliseconds()); }
fn napz(self: *Walk, mill: i64) void { std.Io.sleep(self.iozz, .fromMilliseconds(@min(@max(mill, 1), CF.nmax)), .awake) catch {}; }
fn ori2(aren: std.mem.Allocator, urlz: []const u8) ![]const u8 { const part = try urln.urlzSpli(urlz); return std.fmt.allocPrint(aren, "{s}://{s}{s}{s}", .{ part.sche, part.host, if (part.dflt) "" else ":", if (part.dflt) "" else try std.fmt.allocPrint(aren, "{d}", .{part.port}) }); }
pub fn walkSeed(self: *Walk, urls: []const []const u8) !u32 { var addz: u32 = 0; var aren = std.heap.ArenaAllocator.init(self.gpaz); defer aren.deinit(); for (urls) |urlz| { const norm = urln.urlzNorm(aren.allocator(), urlz) catch continue; const part = try urln.urlzSpli(norm); if (try fron.fronAddz(self.dbzz, norm, part.host, self.nowzMill())) addz += 1; } return addz; }
fn textGetz(self: *Walk, aren: std.mem.Allocator, urlz: []const u8) !struct { code: u16, body: []const u8 } { var opts = try pipe.optsMake(aren, self.conf, self.priv); opts.body_maxz = @min(opts.body_maxz, 20 << 20); var resp = try tmfx.fetcTime(self.gpaz, self.iozz, urlz, opts, .{}); defer resp.free(self.gpaz); return .{ .code = resp.code, .body = try aren.dupe(u8, resp.body) }; }
pub fn walkSmap(self: *Walk, roo2: []const u8) !u32 { var aren = std.heap.ArenaAllocator.init(self.gpaz); defer aren.deinit(); const allo = aren.allocator(); const base = try ori2(allo, roo2); const rob2 = try self.roboGetz(base); var todo: std.ArrayList([]const u8) = .empty; try todo.append(allo, try std.fmt.allocPrint(allo, "{s}/sitemap.xml", .{base})); for (rob2.maps) |item| if (std.mem.startsWith(u8, item, "http")) try todo.append(allo, try allo.dupe(u8, item)); var addz: u32 = 0; var subs: usize = 0; var indx: usize = 0; while (indx < todo.items.len and subs < CF.subz + 1) : (indx += 1) { subs += 1; const got2 = self.textGetz(allo, todo.items[indx]) catch continue; if (got2.code != 200) continue; const rslt = try smap.smapPars(allo, got2.body, CF.smax); if (rslt.indx) { for (rslt.urls) |item| if (todo.items.len < CF.subz + 2) try todo.append(allo, item); } else addz += try self.walkSeed(rslt.urls); } return addz; }
fn roboGetz(self: *Walk, base: []const u8) !robo.Robo { if (self.robs.get(base)) |hitz| return hitz; const parn = self.parn.allocator(); var aren = std.heap.ArenaAllocator.init(self.gpaz); defer aren.deinit(); const urlz = try std.fmt.allocPrint(aren.allocator(), "{s}/robots.txt", .{base}); var robz: robo.Robo = .{}; if (self.textGetz(aren.allocator(), urlz)) |got2| { robz.mode = robo.roboStat(got2.code); if (robz.mode == .pars) robz = try robo.roboPars(parn, got2.body, CF.agnt); } else |_| { robz.mode = .deny; } try self.robs.put(parn, try parn.dupe(u8, base), robz); return robz; }
fn fetcOnez(self: *Walk, aren: std.mem.Allocator, urlz: []const u8) !pipe.Outc { if (self.back) |bckz| { var ladz: ladd.Ladd = .{ .gpaz = self.gpaz, .iozz = self.iozz, .conf = self.conf, .dbzz = self.dbzz, .dirz = self.dirz, .back = bckz, .gozz = self.gozz, .geoz = self.geoz, .priv = self.priv }; return ladd.laddFetc(&ladz, aren, urlz); } return pipe.pageFetc(self.gpaz, aren, self.iozz, self.conf, self.dbzz, self.dirz, urlz, self.priv); }
pub fn walkRevi(self: *Walk, limz: i64) !u32 { var aren = std.heap.ArenaAllocator.init(self.gpaz); defer aren.deinit(); const nowz = self.nowzMill(); const duez = try revi.reviDuez(self.dbzz, aren.allocator(), nowz, limz); var con2: u32 = 0; for (duez) |urlz| { const part = urln.urlzSpli(urlz) catch continue; try revi.reviQueu(self.dbzz, urlz, part.host, nowz); con2 += 1; } return con2; }
fn codeFind(list: []const u32, code: u16) bool { for (list) |item| { if (item == code) return true; } return false; }
fn globAnyz(list: []const []const u8, path: []const u8) bool { for (list) |patn| { if (site.globMach(patn, path)) return true; } return false; }
pub fn sameSite(hosa: []const u8, hosb: []const u8) bool { const hax = if (std.mem.startsWith(u8, hosa, "www.")) hosa[4..] else hosa; const hbx = if (std.mem.startsWith(u8, hosb, "www.")) hosb[4..] else hosb; if (std.ascii.eqlIgnoreCase(hax, hbx)) return true; const lonz = if (hax.len >= hbx.len) hax else hbx; const shrt = if (hax.len >= hbx.len) hbx else hax; return shrt.len > 0 and lonz.len > shrt.len and std.ascii.endsWithIgnoreCase(lonz, shrt) and lonz[lonz.len - shrt.len - 1] == '.'; }
fn fol2(self: *Walk, sum5: *Summ, aren: std.mem.Allocator, item: fron.Item, outc: pipe.Outc, mcfg: cfgz.Conf) !void { var took: u32 = 0; if (self.foll == 0 or outc.hexz.len != 64) return; if (!std.mem.eql(u8, outc.kind, "text") and !std.mem.eql(u8, outc.kind, "ldjs") and !std.mem.eql(u8, outc.kind, "next")) return; const rawd = try std.fs.path.join(aren, &.{ self.dirz, "raw" }); const html = file.fileLoad(aren, self.iozz, rawd, outc.hexz[0..64].*, 20 << 20) catch return; const lin3 = try trap.linkFind(aren, item.urlz, html); const nowz = self.nowzMill(); for (lin3) |lkzz| { if (self.foll == 0) break; if (lkzz.trap and !(mcfg.foll_nofo_enab and std.mem.eql(u8, lkzz.why2, "nofollow"))) { sum5.trap += 1; try inde.logzAddz(self.dbzz, .{ .urlz = lkzz.urlz, .code = 0, .tier = 1, .vend = "", .cred = 0, .micr = 0, .robo = "none", .timz = nowz, .note = try std.fmt.allocPrint(aren, "trap link skipped: {s}", .{lkzz.why2}) }); continue; } const norm = urln.urlzNorm(aren, lkzz.urlz) catch continue; const part = urln.urlzSpli(norm) catch continue; if (!sameSite(item.host, part.host)) continue; if (mcfg.foll_incl_list.len > 0 and !globAnyz(mcfg.foll_incl_list, part.path)) continue; if (globAnyz(mcfg.foll_excl_list, part.path)) continue; if (mcfg.foll_maxz > 0 and took >= mcfg.foll_maxz) break; if (try fron.fronAddz(self.dbzz, norm, part.host, nowz)) { self.foll -= 1; took += 1; } } }
fn permOkay(name: []const u8) bool { for (CF.perm) |item| if (std.mem.eql(u8, item, name)) return true; return false; }
fn failOnez(self: *Walk, sum5: *Summ, urlz: []const u8, errz: []const u8, nowz: i64, perm: bool, push: bool, maxz: i64, base: i64) !void { _ = try fron.fronFail(self.dbzz, urlz, errz, nowz, if (perm) 1 else maxz, base); sum5.fail += 1; if (push) self.brek.push(false); }
fn one2(self: *Walk, sum5: *Summ, item: fron.Item, aren: std.mem.Allocator) !void { try fron.fronLock(self.dbzz, item.urlz); sum5.seen += 1; const part = try urln.urlzSpli(item.urlz); const mcfg = site.siteConf(aren, self.conf, item.host, part.path) catch self.conf; const rmax: i64 = mcfg.retr_cont_maxz; const rbas: i64 = if (mcfg.retr_back_seco > 0) @as(i64, mcfg.retr_back_seco) * 1000 else self.base; const base = try ori2(aren, item.urlz); const rob2 = try self.roboGetz(base); const pqzz = if (part.quer.len > 0) try std.fmt.allocPrint(aren, "{s}?{s}", .{ part.path, part.quer }) else part.path; const decz = robo.roboAllo(rob2, pqzz); var nowz = self.nowzMill(); try inde.logzAddz(self.dbzz, .{ .urlz = item.urlz, .code = 0, .tier = 1, .vend = "", .cred = 0, .micr = 0, .robo = try std.fmt.allocPrint(aren, "{s}: {s}", .{ if (decz.okay) "allow" else "deny", decz.rule }), .timz = nowz, .note = "robots decision" });
if (!decz.okay) { try fron.fronDone(self.dbzz, item.urlz); sum5.skip += 1; return; }
const gapb: i64 = if (mcfg.rate_host_seco != self.conf.rate_host_seco) @as(i64, mcfg.rate_host_seco) * 1000 else self.gapz; var gap2 = @max(gapb, @as(i64, rob2.delz)); if (mcfg.rate_jitt_pctz > 0 and gap2 > 0) { var rbuf: [2]u8 = undefined; self.iozz.random(&rbuf); const rval: i64 = @as(i64, rbuf[0]) | (@as(i64, rbuf[1]) << 8); gap2 += @divFloor(gap2 * @as(i64, mcfg.rate_jitt_pctz) * rval, 6553500); } const outc = self.fetcOnez(aren, item.urlz) catch |err3| { nowz = self.nowzMill(); try self.rate.mark(item.host, nowz, gap2); if (err3 == error.OverCap or err3 == error.KillOn) { self.brek.trip = true; } try self.failOnez(sum5, item.urlz, @errorName(err3), nowz, permOkay(@errorName(err3)), !permOkay(@errorName(err3)), rmax, rbas); return; }; nowz = self.nowzMill(); try self.rate.mark(item.host, nowz, gap2);
if (std.mem.eql(u8, outc.stat, "new") or std.mem.eql(u8, outc.stat, "same") or std.mem.eql(u8, outc.stat, "notm")) { try fron.fronDone(self.dbzz, item.urlz); sum5.done += 1; sum5.uniq += 1; self.brek.push(true); try fol2(self, sum5, aren, item, outc, mcfg); return; }
if (std.mem.eql(u8, outc.stat, "http")) { if (outc.code == 404 or outc.code == 410) { try fron.fronDone(self.dbzz, item.urlz); sum5.done += 1; return; } if ((outc.code == 429 or outc.code == 503) and mcfg.retr_afte_enab) try self.rate.hold(item.host, nowz, @divFloor(@as(i64, outc.retr) * 1000 * @as(i64, mcfg.rate_429z_pctz), 100)); if (outc.code == 401 or outc.code == 403) sum5.blok += 1; const nort = mcfg.retr_code_list.len > 0 and !codeFind(mcfg.retr_code_list, outc.code); try self.failOnez(sum5, item.urlz, try std.fmt.allocPrint(aren, "http {d}", .{outc.code}), nowz, nort, !nort, rmax, rbas); return; }
sum5.blok += 1; try self.failOnez(sum5, item.urlz, outc.stat, nowz, false, true, rmax, rbas); }
pub fn walkRunz(self: *Walk, dec2: ?u32) !Summ { var sum5: Summ = .{}; _ = try fron.fronResu(self.dbzz); while (!self.brek.trip) { var aren = std.heap.ArenaAllocator.init(self.gpaz); defer aren.deinit(); var nowz = self.nowzMill(); const duez = try fron.fronDuez(self.dbzz, aren.allocator(), nowz, CF.batz); if (duez.len == 0) { const soon = try fron.fronSoon(self.dbzz) orelse break; self.napz(soon - nowz); continue; } var pick: ?fron.Item = null; var minw: i64 = CF.nmax; for (duez) |item| { const wait = self.rate.wait(item.host, nowz); if (wait == 0) { pick = item; break; } minw = @min(minw, wait); } if (pick) |item| { try self.one2(&sum5, item, aren.allocator()); } else { self.napz(minw); nowz = self.nowzMill(); } } sum5.halt = self.brek.trip; sum5.dead = try fron.fronCont(self.dbzz, 2); if (dec2) |decl| sum5.incm = sum5.uniq < decl; return sum5; } };
